@Test
void testDir() {
    // invoke enhancer with directory and not recurse
    InvocationResult result = invokeEnhancer("-v " + BASEDIR + "/target/test-classes/enhancer-test-dir");
    String outputString = result.getOutputString();
    String errorString = result.getErrorString();
    Assertions.assertEquals(0, result.getExitValue(), "Wrong exit code from Enhancer with stderr:\n" + errorString);
    Assertions.assertTrue(outputString.contains("enhancer-test-dir"), "Expected directory enhancer-test-dir in message from out:\n" + outputString + " with err:\n" + errorString);
    Assertions.assertTrue(outputString.contains("file1.jdo"), "Expected file file1.jdo in message from out:\n" + outputString + " with err:\n" + errorString);
    Assertions.assertTrue(outputString.contains("file2.class"), "Expected file file2.class in message from out:\n" + outputString + " with err:\n" + errorString);
    Assertions.assertTrue(outputString.contains("file3.jar"), "Expected file file3.jar in message from out:\n" + outputString + " with err:\n" + errorString);
    Assertions.assertFalse(outputString.contains("enhancer-test-subdir"), "Expected no directory enhancer-test-subdir in message from out:\n" + outputString + " with err:\n" + errorString);
    Assertions.assertTrue(outputString.contains("3"), "Expected 3 files to be enhanced in message from out:\n" + outputString + " with err:\n" + errorString);
}

@Test
void testDirRecurse() {
    // invoke enhancer with directory and recurse
    InvocationResult result = invokeEnhancer("-v -r " + BASEDIR + "/target/test-classes/enhancer-test-dir");
    String outputString = result.getOutputString();
    String errorString = result.getErrorString();
    Assertions.assertEquals(0, result.getExitValue(), "Wrong exit code from Enhancer with stderr:
" + errorString);
    Assertions.assertTrue(outputString.contains("enhancer-test-dir"), "Expected directory enhancer-test-dir in message from out:
" + outputString + " with err:
" + errorString);
    Assertions.assertTrue(outputString.contains("enhancer-test-subdir"), "Expected directory enhancer-test-subdir in message from out:
" + outputString + " with err:
" + errorString);
    Assertions.assertTrue(outputString.contains("file1.jdo"), "Expected file file1.jdo in message from out:
" + outputString + " with err:
" + errorString);
    Assertions.assertTrue(outputString.contains("file2.class"), "Expected file file2.class in message from out:
" + outputString + " with err:
" + errorString);
    Assertions.assertTrue(outputString.contains("file3.jar"), "Expected file file3.jar in message from out:
" + outputString + " with err:
" + errorString);
    Assertions.assertTrue(outputString.contains("file4.jdo"), "Expected file file4.jdo in message from out:
" + outputString + " with err:
" + errorString);
    Assertions.assertTrue(outputString.contains("file5.class"), "Expected file file5.class in message from out:
" + outputString + " with err:
" + errorString);
    Assertions.assertTrue(outputString.contains("file6.jar"), "Expected file file6.jar in message from out:
" + outputString + " with err:
" + errorString);
    Assertions.assertTrue(outputString.contains("6"), "Expected 6 files to be enhanced in message from out:
" + outputString + " with err:
" + errorString);
}

