@Test
void testCompareTo() {
    ByteIdentity c1 = new ByteIdentity(Object.class, (byte) 1);
    ByteIdentity c2 = new ByteIdentity(Object.class, (byte) 1);
    ByteIdentity c3 = new ByteIdentity(Object.class, (byte) 2);
    ByteIdentity c4 = new ByteIdentity(Class.class, (byte) 1);
    Assertions.assertEquals(0, c1.compareTo(c2), "Equal ByteIdentity instances compare not equal.");
    Assertions.assertTrue(c1.compareTo(c3) < 0, "Not equal ByteIdentity instances have wrong compareTo result");
    Assertions.assertTrue(c3.compareTo(c1) > 0, "Not equal ByteIdentity instances have wrong compareTo result");
    Assertions.assertTrue(c1.compareTo(c4) > 0, "Not equal ByteIdentity instances have wrong compareTo result");
}

