/**
 * test getMetadata with concrete class name
 */
@Test
public void testConcreteClassName() {
    pm = getPM();
    String className = "org.apache.jdo.tck.pc.company.PartTimeEmployee";
    TypeMetadata metadata = pmf.getMetadata(className);
    Assertions.assertNotNull(metadata, ASSERTION_FAILED + "metadata must not be null for abstract class " + className);
    Metadata parent = metadata.getParent();
    Assertions.assertNotNull(parent, ASSERTION_FAILED + "parent metadata must not be null for concrete class " + className);
    String name = metadata.getName();
    String packageName = ((PackageMetadata) parent).getName();
    Assertions.assertEquals(className, packageName + "." + name, ASSERTION_FAILED + "metadata name and class name must match.");
}

