/**
 * Runs the API Signature Test.
 */
@Test
public void testSignatures() {
    // create a SignatureVerifier instance
    final StringWriter sw = new StringWriter();
    // auto-flushes on println
    final PrintWriter pw = new PrintWriter(sw);
    final boolean quiet = false;
    final boolean verbose = debug;
    final SignatureVerifier verifier = new SignatureVerifier(pw, quiet, verbose);
    // run the signature test
    try {
        // fetch name of signature file
        final String signatureFileName = System.getProperty("jdo.tck.signaturefile");
        if (signatureFileName == null) {
            fail(ASSERTION_FAILED, "No system property defined: jdo.tck.signaturefile");
            return;
        }
        // run the test
        final List<String> signatureFileNames = new ArrayList<>();
        signatureFileNames.add(signatureFileName);
        int status = verifier.test(signatureFileNames);
        // print test's output in case of problems or debugging
        if (status != 0) {
            fail(ASSERTION_FAILED, ("Found problems or signature descrepancies." + NEWLINE + "Test Output: " + NEWLINE + sw));
            logger.debug(sw.toString());
        }
        // print test's output in case of problems or debugging
        if (debug) {
            logger.debug(sw.toString());
        }
    } catch (IOException | ParseException ex) {
        fail(ASSERTION_FAILED, ("Exception caught: " + ex + NEWLINE + "Test Output: " + NEWLINE + sw));
    }
}

/**
 */
@Test
public void test() {
    if (isTestToBePerformed()) {
        // register the default factory
        CompanyFactoryRegistry.registerFactory();
        // get new obj graph to compare persistent graph with
        CompanyModelReader reader = new CompanyModelReader(inputFilename);
        List<Object> rootList = getRootList(reader);
        getPM();
        pm.currentTransaction().begin();
        // compare persisted and new
        int size = rootList.size();
        StringBuilder msg = new StringBuilder();
        for (int i = 0; i < size; i++) {
            DeepEquality expected = (DeepEquality) rootList.get(i);
            Object oid = rootOids.get(i);
            Object persisted = pm.getObjectById(oid);
            EqualityHelper equalityHelper = new EqualityHelper();
            if (!expected.deepCompareFields(persisted, equalityHelper)) {
                if (msg.length() > 0) {
                    msg.append("\n");
                }
                msg.append("Expected this  instance:\n    " + expected + "\n" + "Got persistent instance:" + "\n    " + persisted + "\n" + "Detailed list of differences follows...\n");
                msg.append(equalityHelper.getUnequalBuffer());
            }
        }
        pm.currentTransaction().commit();
        // fail test if at least one of the instances is not the expected one
        if (msg.length() > 0) {
            fail("CompletenessTest failed; see list of failures below:", msg.toString());
        }
    }
}

